import { joinSummaryPrefix } from "./summary-prefix.js";
import { formatNumber, t } from "./i18n.js";

export const databaseLimits = {
  titleLength: 120,
  properties: 20,
  propertyNameLength: 80,
  rows: 200,
  views: 12,
  viewNameLength: 80,
  optionsPerProperty: 30,
  optionNameLength: 80,
  filtersPerView: 8,
  sortsPerView: 8,
  textLength: 2000,
  urlLength: 2000,
  idLength: 64
};

export const databasePropertyTypes = ["title", "text", "number", "select", "multi_select", "checkbox", "date", "url"];
export const databaseViewTypes = ["table", "board", "list"];
const databaseOptionColors = ["gray", "blue", "purple", "green", "yellow", "red", "pink", "orange"];
const databaseFilterOperators = ["contains", "equals", "is_empty", "is_not_empty", "checked", "unchecked"];
const unsafeDatabaseIds = new Set(["__proto__", "constructor", "prototype"]);
const databaseToolbarPanels = [
  { selector: ".database-properties-panel", reopenKey: "openProperties" },
  { selector: ".database-filter-panel", reopenKey: "openFilters" },
  { selector: ".database-sort-panel", reopenKey: "openSorts" },
  { selector: ".database-view-options-panel", reopenKey: "openViewOptions" },
  { selector: ".database-search-panel" },
  { selector: ".database-new-menu" }
];
const openDatabaseToolbarPanelSelector = databaseToolbarPanels
  .map(({ selector }) => `${selector}[open]`)
  .join(",");
// Outside pointer interaction can blur a property field whose change handler
// rebuilds the editor. Keep the dismissal authoritative across that rebuild.
const databaseToolbarLightDismissSuppressions = new WeakMap();

function closestMatchingElement(target, selector) {
  return target && typeof target.closest === "function" ? target.closest(selector) : null;
}

function databaseToolbarPanelEntry(panel) {
  return databaseToolbarPanels.find(({ selector }) => panel?.matches?.(selector)) ?? null;
}

function markDatabaseToolbarLightDismiss(panel) {
  const row = panel?.closest?.(".editor-block-row");
  const entry = databaseToolbarPanelEntry(panel);
  if (!row || !entry?.reopenKey) return;
  const suppressions = databaseToolbarLightDismissSuppressions.get(row) ?? new Set();
  suppressions.add(entry.reopenKey);
  databaseToolbarLightDismissSuppressions.set(row, suppressions);
  setTimeout(() => {
    const current = databaseToolbarLightDismissSuppressions.get(row);
    if (!current) return;
    current.delete(entry.reopenKey);
    if (!current.size) databaseToolbarLightDismissSuppressions.delete(row);
  }, 0);
}

function consumeDatabaseToolbarLightDismiss(row, reopenKey) {
  const suppressions = databaseToolbarLightDismissSuppressions.get(row);
  if (!suppressions?.delete(reopenKey)) return false;
  if (!suppressions.size) databaseToolbarLightDismissSuppressions.delete(row);
  return true;
}

export function dismissDatabaseToolbarPopovers(root, eventTarget = null) {
  if (!root || typeof root.querySelectorAll !== "function") return false;
  const containingOpenPanel = closestMatchingElement(eventTarget, openDatabaseToolbarPanelSelector);
  let dismissed = false;
  root.querySelectorAll(openDatabaseToolbarPanelSelector).forEach((panel) => {
    if (panel === containingOpenPanel) return;
    markDatabaseToolbarLightDismiss(panel);
    panel.removeAttribute("open");
    dismissed = true;
  });
  return dismissed;
}

function createId(prefix) {
  const random = globalThis.crypto?.randomUUID?.() ?? `${Date.now()}-${Math.random().toString(36).slice(2)}`;
  return `${prefix}-${random}`.slice(0, databaseLimits.idLength);
}

function recordValue(value) {
  return value && typeof value === "object" && !Array.isArray(value) ? value : null;
}

function collectRecordValues(value, limit, recoverableKeys) {
  if (!Array.isArray(value) || limit <= 0) return [];
  const records = [];
  for (const item of value) {
    const record = recordValue(item);
    if (
      !record
      || !recoverableKeys.some((key) => Object.prototype.hasOwnProperty.call(record, key))
    ) continue;
    records.push(record);
    if (records.length >= limit) break;
  }
  return records;
}

function stringValue(value, fallback, maxLength) {
  return (typeof value === "string" ? value : fallback).slice(0, maxLength);
}

function safeId(value, fallback) {
  const id = typeof value === "string" ? value.trim().slice(0, databaseLimits.idLength) : "";
  if (id && !unsafeDatabaseIds.has(id)) return id;
  const fallbackId = fallback.slice(0, databaseLimits.idLength);
  return fallbackId && !unsafeDatabaseIds.has(fallbackId) ? fallbackId : "";
}

function uniqueId(value, seen, fallbackPrefix) {
  let id = value.slice(0, databaseLimits.idLength);
  let attempt = 1;
  while (seen.has(id)) {
    const suffix = `-${attempt}`;
    const prefixLength = Math.max(0, databaseLimits.idLength - suffix.length);
    id = `${fallbackPrefix.slice(0, prefixLength)}${suffix}`;
    attempt += 1;
  }
  seen.add(id);
  return id;
}

function createIdAliases() {
  return { exact: new Map(), generated: new Map(), normalized: new Map() };
}

function sourceStringId(value) {
  return typeof value === "string" ? value : null;
}

function sourceUsesFallbackId(value) {
  const id = typeof value === "string" ? value.trim().slice(0, databaseLimits.idLength) : "";
  return !id || unsafeDatabaseIds.has(id);
}

function registerExactIdAlias(aliases, sourceId, canonicalId) {
  if (sourceId && !aliases.exact.has(sourceId) && !aliases.generated.has(sourceId)) {
    aliases.exact.set(sourceId, canonicalId);
  }
}

function registerGeneratedIdAliases(aliases, requestedId, canonicalId) {
  [requestedId, canonicalId].forEach((alias) => {
    if (!alias || aliases.exact.has(alias) || aliases.generated.has(alias)) return;
    aliases.generated.set(alias, canonicalId);
  });
}

function registerGeneratedIdOwnership(aliases, sourceId, requestedId, canonicalId) {
  const requestedWasGenerated = sourceUsesFallbackId(sourceId);
  if (!requestedWasGenerated && canonicalId === requestedId) return;
  registerGeneratedIdAliases(
    aliases,
    requestedWasGenerated ? requestedId : "",
    canonicalId
  );
}

function registerNormalizedIdAlias(aliases, requestedId, canonicalId) {
  [requestedId, canonicalId].forEach((alias) => {
    if (
      !alias
      || aliases.exact.has(alias)
      || aliases.generated.has(alias)
      || aliases.normalized.has(alias)
    ) return;
    aliases.normalized.set(alias, canonicalId);
  });
}

function resolveIdReference(value, aliases) {
  if (typeof value !== "string") return "";
  const exact = aliases.exact.get(value);
  if (exact !== undefined) return exact;
  const generated = aliases.generated.get(value);
  if (generated !== undefined) return generated;
  const normalized = safeId(value, "");
  if (!normalized) return "";
  return aliases.exact.get(normalized)
    ?? aliases.generated.get(normalized)
    ?? aliases.normalized.get(normalized)
    ?? normalized;
}

function normalizePropertyType(value) {
  return databasePropertyTypes.includes(value) ? value : "text";
}

function normalizeViewType(value) {
  return databaseViewTypes.includes(value) ? value : "table";
}

function normalizeOptionColor(value, index) {
  return databaseOptionColors.includes(value) ? value : databaseOptionColors[index % databaseOptionColors.length];
}

function normalizeOptions(value, propertyId) {
  const aliases = createIdAliases();
  if (!Array.isArray(value)) return { options: [], aliases };
  const seen = new Set();
  const descriptors = collectRecordValues(value, databaseLimits.optionsPerProperty, ["id", "name", "color"])
    .map((item, index) => {
      const sourceId = sourceStringId(item.id);
      const requestedId = safeId(item.id, `${propertyId}-option-${index + 1}`);
      const id = uniqueId(requestedId, seen, `${propertyId}-option-${index + 1}`);
      registerGeneratedIdOwnership(aliases, item.id, requestedId, id);
      registerExactIdAlias(aliases, sourceId, id);
      return {
        sourceId,
        requestedId,
        option: {
          id,
          name: stringValue(item.name, `Option ${index + 1}`, databaseLimits.optionNameLength),
          color: normalizeOptionColor(item.color, index)
        }
      };
    });
  descriptors.forEach((descriptor) => {
    registerNormalizedIdAlias(aliases, descriptor.requestedId, descriptor.option.id);
  });
  return { options: descriptors.map((descriptor) => descriptor.option), aliases };
}

function createDatabaseOptionValidationError(code, details = {}) {
  const error = new Error(code);
  error.code = code;
  Object.assign(error, details);
  return error;
}

export function parseDatabaseOptionNames(value) {
  const names = (typeof value === "string" ? value : "")
    .split(",")
    .map((name) => name.trim())
    .filter(Boolean);

  if (names.length > databaseLimits.optionsPerProperty) {
    throw createDatabaseOptionValidationError("too-many-options", {
      maximum: databaseLimits.optionsPerProperty
    });
  }

  const seen = new Set();
  for (const name of names) {
    if (name.length > databaseLimits.optionNameLength) {
      throw createDatabaseOptionValidationError("option-name-too-long", {
        maximum: databaseLimits.optionNameLength
      });
    }

    const normalizedName = name.toLocaleLowerCase();
    if (seen.has(normalizedName)) {
      throw createDatabaseOptionValidationError("duplicate-option", { name });
    }
    seen.add(normalizedName);
  }

  return names;
}

function databaseOptionIsReferenced(database, property, optionId) {
  const rowReference = database.rows.some((dataRow) => {
    const value = dataRow.values[property.id];
    if (property.type === "select") return value === optionId;
    return Array.isArray(value) && value.includes(optionId);
  });
  if (rowReference) return true;

  return database.views.some((view) => view.filters.some(
    (filter) => filter.propertyId === property.id && filter.value === optionId
  ));
}

export function reconcileDatabaseOptions(database, property, names) {
  const previous = property.options;
  const usedOptionIds = new Set();
  const next = Array(names.length).fill(null);

  names.forEach((name, index) => {
    const normalizedName = name.toLocaleLowerCase();
    const existing = previous.find(
      (option) => !usedOptionIds.has(option.id)
        && option.name.toLocaleLowerCase() === normalizedName
    );
    if (!existing) return;
    next[index] = { ...existing, name };
    usedOptionIds.add(existing.id);
  });

  let unmatchedOld = previous.filter((option) => !usedOptionIds.has(option.id));
  let unmatchedNewIndexes = next
    .map((option, index) => option ? null : index)
    .filter((index) => index !== null);

  // A single old/new mismatch is the only rename that the comma-separated
  // editor can identify without ambiguity. Preserve the option ID so every
  // existing row and filter continues to reference the same logical option.
  if (unmatchedOld.length === 1 && unmatchedNewIndexes.length === 1) {
    const oldOption = unmatchedOld[0];
    const index = unmatchedNewIndexes[0];
    next[index] = { ...oldOption, name: names[index] };
    usedOptionIds.add(oldOption.id);
    unmatchedOld = [];
    unmatchedNewIndexes = [];
  } else if (unmatchedOld.length > 0 && unmatchedNewIndexes.length > 0) {
    throw createDatabaseOptionValidationError("ambiguous-option-edit");
  }

  for (const index of unmatchedNewIndexes) {
    next[index] = {
      id: createId("option"),
      name: names[index],
      color: databaseOptionColors[index % databaseOptionColors.length]
    };
  }

  for (const option of unmatchedOld) {
    if (databaseOptionIsReferenced(database, property, option.id)) {
      throw createDatabaseOptionValidationError("referenced-option-removal", {
        name: option.name
      });
    }
  }

  return next.filter(Boolean);
}

function databaseOptionValidationMessage(error) {
  switch (error?.code) {
    case "too-many-options":
      return t("database.optionsTooMany", { count: error.maximum });
    case "option-name-too-long":
      return t("database.optionNameTooLong", { count: error.maximum });
    case "duplicate-option":
      return t("database.duplicateOption", { option: error.name });
    case "ambiguous-option-edit":
      return t("database.ambiguousOptionEdit");
    case "referenced-option-removal":
      return t("database.referencedOptionRemoval", { option: error.name });
    default:
      return t("database.invalidOptions");
  }
}

function normalizeFilterValue(value) {
  if (typeof value === "boolean") return value;
  if (typeof value === "number") return Number.isFinite(value) ? value : null;
  if (typeof value === "string") return value.slice(0, databaseLimits.textLength);
  return null;
}

function normalizePropertyValue(property, value) {
  if (property.type === "number") {
    if (value === null || value === "" || value === undefined) return null;
    const number = Number(value);
    return Number.isFinite(number) ? number : null;
  }
  if (property.type === "checkbox") return value === true;
  if (property.type === "select") {
    const optionId = typeof value === "string" ? value : "";
    return property.options.some((option) => option.id === optionId) ? optionId : "";
  }
  if (property.type === "multi_select") {
    const values = Array.isArray(value) ? value : [];
    return [...new Set(values.filter((item) => typeof item === "string"))]
      .filter((id) => property.options.some((option) => option.id === id))
      .slice(0, databaseLimits.optionsPerProperty);
  }
  if (property.type === "date") return stringValue(value, "", 32);
  if (property.type === "url") return stringValue(value, "", databaseLimits.urlLength);
  return stringValue(value, "", databaseLimits.textLength);
}

function readSourcePropertyValue(sourceValues, descriptor, propertyAliases) {
  const candidates = [descriptor.sourceId, descriptor.requestedId, descriptor.property.id];
  const seen = new Set();
  for (const candidate of candidates) {
    if (!candidate || seen.has(candidate)) continue;
    seen.add(candidate);
    if (!Object.prototype.hasOwnProperty.call(sourceValues, candidate)) continue;
    if (resolveIdReference(candidate, propertyAliases) !== descriptor.property.id) continue;
    return sourceValues[candidate];
  }
  return undefined;
}

function normalizeReferencedPropertyValue(descriptor, value) {
  if (descriptor.property.type === "select" && typeof value === "string") {
    return normalizePropertyValue(descriptor.property, resolveIdReference(value, descriptor.optionAliases));
  }
  if (descriptor.property.type === "multi_select" && Array.isArray(value)) {
    const remapped = value.map((item) =>
      typeof item === "string" ? resolveIdReference(item, descriptor.optionAliases) : item
    );
    return normalizePropertyValue(descriptor.property, remapped);
  }
  return normalizePropertyValue(descriptor.property, value);
}

function normalizeFilterValueForProperty(descriptor, value) {
  if (["select", "multi_select"].includes(descriptor.property.type) && typeof value === "string") {
    const remapped = resolveIdReference(value, descriptor.optionAliases);
    if (descriptor.property.options.some((option) => option.id === remapped)) return remapped;
  }
  return normalizeFilterValue(value);
}

export function createDefaultDatabaseData() {
  const tableViewId = createId("view");
  const boardViewId = createId("view");
  return {
    title: t("database.defaultTitle"),
    properties: [
      { id: "title", name: t("database.defaultNameProperty"), type: "title", options: [] },
      {
        id: "status",
        name: t("database.defaultStatusProperty"),
        type: "select",
        options: [
          { id: "not-started", name: t("database.defaultNotStarted"), color: "gray" },
          { id: "in-progress", name: t("database.defaultInProgress"), color: "blue" },
          { id: "done", name: t("database.defaultDone"), color: "green" }
        ]
      },
      { id: "tags", name: t("database.defaultTagsProperty"), type: "multi_select", options: [] },
      { id: "due", name: t("database.defaultDueProperty"), type: "date", options: [] },
      { id: "complete", name: t("database.defaultCompleteProperty"), type: "checkbox", options: [] }
    ],
    rows: [
      {
        id: createId("row"),
        values: { title: "", status: "not-started", tags: [], due: "", complete: false }
      }
    ],
    views: [
      {
        id: tableViewId,
        name: t("database.tableView"),
        type: "table",
        filters: [],
        sorts: [],
        groupPropertyId: null,
        hiddenPropertyIds: []
      },
      {
        id: boardViewId,
        name: t("database.boardView"),
        type: "board",
        filters: [],
        sorts: [],
        groupPropertyId: "status",
        hiddenPropertyIds: ["status"]
      }
    ],
    activeViewId: tableViewId
  };
}

function createDatabaseNormalizationFallback() {
  return {
    title: "Database",
    views: [
      {
        id: "table-view",
        name: "Table",
        type: "table",
        filters: [],
        sorts: [],
        groupPropertyId: null,
        hiddenPropertyIds: []
      },
      {
        id: "board-view",
        name: "Board",
        type: "board",
        filters: [],
        sorts: [],
        groupPropertyId: "status",
        hiddenPropertyIds: ["status"]
      }
    ]
  };
}

export function normalizeDatabaseData(value) {
  const source = recordValue(value) ?? {};
  const fallback = createDatabaseNormalizationFallback();
  const propertySources = collectRecordValues(source.properties, databaseLimits.properties, ["id", "name", "type", "options"]);
  const seenPropertyIds = new Set();
  const propertyAliases = createIdAliases();
  let titleSeen = false;
  const propertyDescriptors = propertySources
    .map((item, index) => {
      const sourceId = sourceStringId(item.id);
      const requestedId = safeId(item.id, `property-${index + 1}`);
      const id = uniqueId(requestedId, seenPropertyIds, `property-${index + 1}`);
      registerGeneratedIdOwnership(propertyAliases, item.id, requestedId, id);
      registerExactIdAlias(propertyAliases, sourceId, id);
      let type = normalizePropertyType(item.type);
      if (type === "title") {
        if (titleSeen) type = "text";
        else titleSeen = true;
      }
      const normalizedOptions = type === "select" || type === "multi_select"
        ? normalizeOptions(item.options, id)
        : { options: [], aliases: createIdAliases() };
      return {
        sourceId,
        requestedId,
        property: {
          id,
          name: stringValue(
            item.name,
            type === "title" ? "Name" : `Property ${index + 1}`,
            databaseLimits.propertyNameLength
          ),
          type,
          options: normalizedOptions.options
        },
        optionAliases: normalizedOptions.aliases
      };
    });

  // Preserve every field in a full-capacity legacy model without a title. Adding a
  // synthetic 21st property would make the next normalization drop the final field.
  if (!titleSeen && propertyDescriptors.length < databaseLimits.properties) {
    const id = uniqueId("title", seenPropertyIds, "title");
    propertyDescriptors.unshift({
      sourceId: null,
      requestedId: id,
      property: { id, name: "Name", type: "title", options: [] },
      optionAliases: createIdAliases()
    });
  }

  propertyDescriptors.forEach((descriptor) => {
    registerNormalizedIdAlias(propertyAliases, descriptor.requestedId, descriptor.property.id);
  });
  const properties = propertyDescriptors.map((descriptor) => descriptor.property);
  const propertyById = new Map(properties.map((property) => [property.id, property]));
  const propertyDescriptorById = new Map(
    propertyDescriptors.map((descriptor) => [descriptor.property.id, descriptor])
  );

  const rowSources = collectRecordValues(source.rows, databaseLimits.rows, ["id", "values"]);
  const seenRowIds = new Set();
  const rows = rowSources
    .map((item, index) => {
      const id = uniqueId(safeId(item.id, `row-${index + 1}`), seenRowIds, `row-${index + 1}`);
      const sourceValues = recordValue(item.values) ?? {};
      const values = {};
      propertyDescriptors.forEach((descriptor) => {
        const sourceValue = readSourcePropertyValue(sourceValues, descriptor, propertyAliases);
        values[descriptor.property.id] = normalizeReferencedPropertyValue(descriptor, sourceValue);
      });
      return { id, values };
    });

  const viewSources = collectRecordValues(
    source.views,
    databaseLimits.views,
    ["id", "name", "type", "filters", "sorts", "groupPropertyId", "hiddenPropertyIds"]
  );
  const seenViewIds = new Set();
  const viewAliases = createIdAliases();
  const viewDescriptors = viewSources
    .map((item, index) => {
      const sourceId = sourceStringId(item.id);
      const requestedId = safeId(item.id, `view-${index + 1}`);
      const id = uniqueId(requestedId, seenViewIds, `view-${index + 1}`);
      registerGeneratedIdOwnership(viewAliases, item.id, requestedId, id);
      registerExactIdAlias(viewAliases, sourceId, id);
      const type = normalizeViewType(item.type);
      const filterSources = [];
      if (Array.isArray(item.filters)) {
        for (const candidate of item.filters) {
          const filter = recordValue(candidate);
          if (!filter) continue;
          const propertyId = resolveIdReference(filter.propertyId, propertyAliases);
          if (!propertyById.has(propertyId)) continue;
          filterSources.push({ filter, propertyId });
          if (filterSources.length >= databaseLimits.filtersPerView) break;
        }
      }
      const seenFilterIds = new Set();
      const filters = filterSources.map(({ filter, propertyId }, filterIndex) => {
        const propertyDescriptor = propertyDescriptorById.get(propertyId);
        return {
          id: uniqueId(
            safeId(filter.id, `${id}-filter-${filterIndex + 1}`),
            seenFilterIds,
            `${id}-filter-${filterIndex + 1}`
          ),
          propertyId,
          operator: databaseFilterOperators.includes(filter.operator) ? filter.operator : "contains",
          value: propertyDescriptor
            ? normalizeFilterValueForProperty(propertyDescriptor, filter.value)
            : normalizeFilterValue(filter.value)
        };
      });
      const sortSources = [];
      if (Array.isArray(item.sorts)) {
        for (const candidate of item.sorts) {
          const sort = recordValue(candidate);
          if (!sort) continue;
          const propertyId = resolveIdReference(sort.propertyId, propertyAliases);
          if (!propertyById.has(propertyId)) continue;
          sortSources.push({ sort, propertyId });
          if (sortSources.length >= databaseLimits.sortsPerView) break;
        }
      }
      const seenSortIds = new Set();
      const sorts = sortSources.map(({ sort, propertyId }, sortIndex) => ({
        id: uniqueId(
          safeId(sort.id, `${id}-sort-${sortIndex + 1}`),
          seenSortIds,
          `${id}-sort-${sortIndex + 1}`
        ),
        propertyId,
        direction: sort.direction === "descending" ? "descending" : "ascending"
      }));
      const requestedGroupPropertyId = resolveIdReference(item.groupPropertyId, propertyAliases);
      const groupProperty = propertyById.get(requestedGroupPropertyId);
      const view = {
        id,
        name: stringValue(
          item.name,
          type === "board" ? "Board" : type === "list" ? "List" : "Table",
          databaseLimits.viewNameLength
        ),
        type,
        filters,
        sorts,
        groupPropertyId: type === "board" && groupProperty && ["select", "checkbox"].includes(groupProperty.type)
          ? groupProperty.id
          : null,
        hiddenPropertyIds: Array.isArray(item.hiddenPropertyIds)
          ? [...new Set(item.hiddenPropertyIds
            .filter((propertyId) => typeof propertyId === "string")
            .map((propertyId) => resolveIdReference(propertyId, propertyAliases)))]
            .filter((propertyId) => propertyById.has(propertyId) && propertyById.get(propertyId).type !== "title")
          : []
      };
      return { sourceId, requestedId, view };
    });

  viewDescriptors.forEach((descriptor) => {
    registerNormalizedIdAlias(viewAliases, descriptor.requestedId, descriptor.view.id);
  });
  const views = viewDescriptors.map((descriptor) => descriptor.view);

  const fallbackViews = fallback.views.map((view) => {
    const requestedGroupProperty = view.groupPropertyId
      ? propertyById.get(view.groupPropertyId)
      : null;
    return {
      ...view,
      groupPropertyId: view.type === "board"
        && requestedGroupProperty
        && ["select", "checkbox"].includes(requestedGroupProperty.type)
        ? requestedGroupProperty.id
        : null,
      hiddenPropertyIds: view.hiddenPropertyIds.filter(
        (propertyId) => propertyById.has(propertyId) && propertyById.get(propertyId)?.type !== "title"
      )
    };
  });
  const normalizedViews = views.length ? views : fallbackViews;
  const requestedActiveViewId = resolveIdReference(source.activeViewId, viewAliases);
  const activeViewId = normalizedViews.some((view) => view.id === requestedActiveViewId)
    ? requestedActiveViewId
    : normalizedViews[0].id;

  return {
    title: stringValue(source.title, fallback.title, databaseLimits.titleLength),
    properties,
    rows,
    views: normalizedViews,
    activeViewId
  };
}

export function getDatabaseActiveView(database) {
  return database.views.find((view) => view.id === database.activeViewId) ?? database.views[0];
}

function getTitleProperty(database) {
  return database.properties.find((property) => property.type === "title") ?? database.properties[0];
}

function getOption(property, optionId) {
  return property.options.find((option) => option.id === optionId) ?? null;
}

function isEmptyValue(value) {
  return value === null || value === "" || (Array.isArray(value) && value.length === 0);
}

function searchableValue(property, value) {
  if (property.type === "select") return getOption(property, value)?.name ?? "";
  if (property.type === "multi_select") {
    return Array.isArray(value)
      ? value.map((id) => getOption(property, id)?.name ?? "").join(" ")
      : "";
  }
  if (property.type === "checkbox") return value === true ? "true checked" : "false unchecked";
  return value === null || value === undefined ? "" : String(value);
}

function rowMatchesFilter(dataRow, filter, propertyById) {
  const property = propertyById.get(filter.propertyId);
  if (!property) return true;
  const value = dataRow.values[property.id];
  if (filter.operator === "is_empty") return isEmptyValue(value);
  if (filter.operator === "is_not_empty") return !isEmptyValue(value);
  if (filter.operator === "checked") return value === true;
  if (filter.operator === "unchecked") return value !== true;
  if (property.type === "number") {
    const filterNumber = Number(filter.value);
    return Number.isFinite(filterNumber) && value === filterNumber;
  }
  if (property.type === "select") return value === filter.value;
  if (property.type === "multi_select") {
    const values = Array.isArray(value) ? value : [];
    return filter.operator === "equals"
      ? values.length === 1 && values[0] === filter.value
      : values.includes(String(filter.value ?? ""));
  }
  const left = searchableValue(property, value).toLocaleLowerCase();
  const right = String(filter.value ?? "").toLocaleLowerCase();
  return filter.operator === "equals" ? left === right : left.includes(right);
}

function compareValues(property, left, right, compareText) {
  if (isEmptyValue(left) && isEmptyValue(right)) return 0;
  if (isEmptyValue(left)) return 1;
  if (isEmptyValue(right)) return -1;
  if (property.type === "number") return Number(left) - Number(right);
  if (property.type === "checkbox") return Number(Boolean(left)) - Number(Boolean(right));
  return compareText(searchableValue(property, left), searchableValue(property, right));
}

export function applyDatabaseView(database, view = getDatabaseActiveView(database)) {
  const propertyById = new Map(database.properties.map((property) => [property.id, property]));
  const rows = database.rows.filter((dataRow) => view.filters.every((filter) => rowMatchesFilter(dataRow, filter, propertyById)));
  if (!view.sorts.length) return rows;
  // Scope the collator to this invocation: locale and edited labels stay fresh,
  // and numeric/empty-only sorts never allocate an internationalized comparator.
  let collator;
  const compareText = (left, right) => {
    collator ??= new Intl.Collator(undefined, { numeric: true, sensitivity: "base" });
    return collator.compare(left, right);
  };
  // filter() already owns this array; sorting it cannot mutate database.rows.
  return rows.sort((left, right) => {
    for (const sort of view.sorts) {
      const property = propertyById.get(sort.propertyId);
      if (!property) continue;
      const result = compareValues(property, left.values[property.id], right.values[property.id], compareText);
      if (result) return sort.direction === "descending" ? -result : result;
    }
    return 0;
  });
}

function applyDatabaseSearch(database, rows, query) {
  const normalizedQuery = String(query ?? "").trim().toLocaleLowerCase();
  if (!normalizedQuery) return rows;
  return rows.filter((dataRow) => database.properties.some((property) =>
    searchableValue(property, dataRow.values[property.id]).toLocaleLowerCase().includes(normalizedQuery)
  ));
}

