const databaseUrlPreviewCache = new Map();
const databaseUrlPreviewCacheMaxEntries = 250;
const databaseUrlPreviewObservers = new WeakMap();

function getDatabasePreviewUrl(value) {
  const raw = typeof value === "string" ? value.trim() : "";
  if (!raw) return null;
  try {
    const url = new URL(raw);
    if (!["http:", "https:"].includes(url.protocol) || url.username || url.password) return null;
    return url;
  } catch {
    return null;
  }
}

const databaseUrlPreviewFaviconDataUrlMaxLength = Math.ceil((128 * 1024 * 4) / 3) + 128;
const databaseUrlPreviewFaviconDataPattern = /^data:image\/(?:png|jpeg|gif|webp|vnd\.microsoft\.icon);base64,[a-z0-9+/]+={0,2}$/i;

function getDatabasePreviewImageUrl(value) {
  const raw = typeof value === "string" ? value.trim() : "";
  if (
    raw.length <= databaseUrlPreviewFaviconDataUrlMaxLength
    && databaseUrlPreviewFaviconDataPattern.test(raw)
  ) return raw;
  const url = getDatabasePreviewUrl(raw);
  return url?.toString() ?? "";
}

function resetDatabaseUrlPreview(preview, value) {
  const raw = typeof value === "string" ? value : "";
  const url = getDatabasePreviewUrl(raw);
  preview.replaceChildren();
  preview.classList.toggle("is-empty", !raw);
  preview.classList.toggle("is-invalid", Boolean(raw) && !url);
  preview.dataset.previewState = url ? "pending" : "idle";

  if (url) {
    const normalizedUrl = url.toString();
    preview.href = normalizedUrl;
    preview.dataset.url = normalizedUrl;
  } else {
    preview.removeAttribute("href");
    delete preview.dataset.url;
  }

  const faviconSlot = document.createElement("span");
  faviconSlot.className = "database-url-preview-favicon";
  faviconSlot.setAttribute("aria-hidden", "true");

  const title = document.createElement("span");
  title.className = "database-url-preview-title";
  title.textContent = url ? url.hostname : raw;
  preview.append(faviconSlot, title);
}

function applyDatabaseUrlPreview(preview, previewData, requestedUrl) {
  if (!preview?.isConnected || preview.dataset.url !== requestedUrl) return;
  const title = typeof previewData?.title === "string" ? previewData.title.trim() : "";
  const titleElement = preview.querySelector(".database-url-preview-title");
  if (titleElement && title) titleElement.textContent = title;

  const faviconUrl = getDatabasePreviewImageUrl(previewData?.faviconUrl);
  const faviconSlot = preview.querySelector(".database-url-preview-favicon");
  if (faviconSlot) {
    faviconSlot.replaceChildren();
    if (faviconUrl) {
      const image = document.createElement("img");
      image.src = faviconUrl;
      image.alt = "";
      image.width = 16;
      image.height = 16;
      image.loading = "lazy";
      image.referrerPolicy = "no-referrer";
      image.addEventListener("error", () => image.remove(), { once: true });
      faviconSlot.append(image);
    }
  }
  preview.dataset.previewState = "loaded";
}

function getDatabaseUrlPreviewRequest(url, fetchPreview) {
  const cached = databaseUrlPreviewCache.get(url);
  if (cached) {
    // Keep frequently reused previews resident when one-off URLs churn through
    // the bounded cache; Map iteration order is insertion order.
    databaseUrlPreviewCache.delete(url);
    databaseUrlPreviewCache.set(url, cached);
    return cached;
  }

  const request = Promise.resolve()
    .then(() => fetchPreview(url))
    .then((value) => value?.preview ?? value ?? null)
    .catch(() => null)
    .then((value) => {
      // Do not let a late failure from an evicted request delete a newer
      // in-flight/result entry for the same URL.
      if (!value && databaseUrlPreviewCache.get(url) === request) {
        databaseUrlPreviewCache.delete(url);
      }
      return value;
    });
  databaseUrlPreviewCache.set(url, request);
  if (databaseUrlPreviewCache.size > databaseUrlPreviewCacheMaxEntries) {
    const oldest = databaseUrlPreviewCache.keys().next().value;
    if (oldest) databaseUrlPreviewCache.delete(oldest);
  }
  return request;
}

async function hydrateDatabaseUrlPreview(preview, fetchPreview) {
  const url = preview?.dataset?.url;
  if (!url || preview.dataset.previewState === "loading" || preview.dataset.previewState === "loaded") return;
  preview.dataset.previewState = "loading";
  const previewData = await getDatabaseUrlPreviewRequest(url, fetchPreview);
  if (!preview?.isConnected || preview.dataset.url !== url) return;
  if (!previewData) {
    preview.dataset.previewState = "failed";
    return;
  }
  applyDatabaseUrlPreview(preview, previewData, url);
}

export function hydrateDatabaseUrlPreviews(root, fetchPreview) {
  if (!root || typeof fetchPreview !== "function") return;
  // `root` is normally the long-lived page view. Release targets from the
  // previous render even when the new render has no URL previews, otherwise an
  // IntersectionObserver can keep detached offscreen preview nodes registered.
  let observerState = databaseUrlPreviewObservers.get(root);
  observerState?.observer?.disconnect();
  const previews = [...root.querySelectorAll(".database-url-preview[data-url]")]
    .filter((preview) => !["loading", "loaded"].includes(preview.dataset.previewState));
  if (!previews.length) return;

  if (typeof IntersectionObserver !== "function") {
    previews.forEach((preview) => { void hydrateDatabaseUrlPreview(preview, fetchPreview); });
    return;
  }

  if (!observerState || observerState.fetchPreview !== fetchPreview) {
    const observer = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (!entry.isIntersecting) return;
        observer.unobserve(entry.target);
        void hydrateDatabaseUrlPreview(entry.target, fetchPreview);
      });
    }, { rootMargin: "160px" });
    observerState = { observer, fetchPreview };
    databaseUrlPreviewObservers.set(root, observerState);
  }
  previews.forEach((preview) => observerState.observer.observe(preview));
}

function createValueEditor(dataRow, property, { compact = false, onDirty, onStructuralChange = null } = {}) {
  const value = dataRow.values[property.id];
  let control;
  let urlPreview = null;
  let urlValue = null;

  if (property.type === "checkbox") {
    control = document.createElement("input");
    control.type = "checkbox";
    control.checked = value === true;
  } else if (property.type === "select") {
    control = makeSelect(
      [{ value: "", label: t("database.noValue") }, ...property.options.map((option) => ({ value: option.id, label: option.name }))],
      typeof value === "string" ? value : "",
      "database-value-select",
      property.name
    );
    control.classList.add("database-select-chip");
    control.dataset.optionColor = getOption(property, control.value)?.color ?? "gray";
  } else {
    control = document.createElement("input");
    control.type = property.type === "number" ? "number" : property.type === "date" ? "date" : "text";
    control.value = property.type === "multi_select"
      ? (Array.isArray(value) ? value.map((id) => getOption(property, id)?.name).filter(Boolean).join(", ") : "")
      : value === null || value === undefined ? "" : String(value);
    control.maxLength = property.type === "url" ? databaseLimits.urlLength : databaseLimits.textLength;
    if (property.type === "url") control.inputMode = "url";
    if (property.type === "number") control.inputMode = "decimal";
    control.placeholder = property.type === "multi_select" ? t("database.multiSelectPlaceholder") : "";
  }

  control.classList.add("database-value-input");
  if (compact) control.classList.add("is-compact");
  control.dataset.rowId = dataRow.id;
  control.dataset.propertyId = property.id;
  control.setAttribute("aria-label", t("database.valueAria", { property: property.name }));

  if (property.type === "url") {
    urlValue = document.createElement("span");
    urlValue.className = "database-url-value";
    if (compact) urlValue.classList.add("is-compact");
    urlPreview = document.createElement("a");
    urlPreview.className = "database-url-preview";
    urlPreview.target = "_blank";
    urlPreview.rel = "noopener noreferrer";
    urlPreview.referrerPolicy = "no-referrer";
    resetDatabaseUrlPreview(urlPreview, control.value);
    urlValue.append(control, urlPreview);
  }

  const updateEvent = property.type === "checkbox" || property.type === "select" || property.type === "date" ? "change" : "input";
  const update = () => {
    if (property.type === "checkbox") dataRow.values[property.id] = control.checked;
    else if (property.type === "number") dataRow.values[property.id] = control.value === "" ? null : Number(control.value);
    else if (property.type === "multi_select") {
      const names = control.value.split(",").map((item) => item.trim().toLocaleLowerCase()).filter(Boolean);
      dataRow.values[property.id] = property.options
        .filter((option) => names.includes(option.name.toLocaleLowerCase()))
        .map((option) => option.id);
    } else dataRow.values[property.id] = control.value;
    if (property.type === "select") control.dataset.optionColor = getOption(property, control.value)?.color ?? "gray";
    if (urlPreview) resetDatabaseUrlPreview(urlPreview, control.value);
    onDirty();
    if (onStructuralChange && updateEvent === "change") onStructuralChange();
  };

  control.addEventListener(updateEvent, update);
  if (onStructuralChange && updateEvent === "input") control.addEventListener("change", onStructuralChange);
  return urlValue ?? control;
}

function createPropertyManager(editor, row, database, onDirty, replaceEditor) {
  const details = document.createElement("details");
  details.className = "database-properties-panel";

  const summary = document.createElement("summary");
  summary.textContent = t("database.properties");
  details.append(summary);

  const list = document.createElement("div");
  list.className = "database-property-list";

  database.properties.forEach((property) => {
    const item = document.createElement("div");
    item.className = "database-property-item";
    item.dataset.propertyId = property.id;

    const name = document.createElement("input");
    name.type = "text";
    name.className = "database-property-name";
    name.value = property.name;
    name.maxLength = databaseLimits.propertyNameLength;
    name.setAttribute("aria-label", t("database.propertyName"));
    name.addEventListener("input", () => {
      property.name = name.value.slice(0, databaseLimits.propertyNameLength);
      editor.querySelectorAll(`[data-property-label="${CSS.escape(property.id)}"]`).forEach((label) => {
        label.textContent = property.name;
      });
      onDirty();
    });

    const type = makeSelect(
      databasePropertyTypes.map((propertyType) => ({
        value: propertyType,
        label: propertyTypeLabel(propertyType),
        disabled: property.type === "title" ? propertyType !== "title" : propertyType === "title"
      })),
      property.type,
      "database-property-type",
      t("database.propertyType")
    );
    type.disabled = property.type === "title";
    type.addEventListener("change", () => {
      property.type = normalizePropertyType(type.value);
      if (!["select", "multi_select"].includes(property.type)) property.options = [];
      database.rows.forEach((dataRow) => {
        dataRow.values[property.id] = normalizePropertyValue(property, dataRow.values[property.id]);
      });
      replaceEditor({ openProperties: true, focusPropertyId: property.id });
    });

    item.append(name, type);

    if (["select", "multi_select"].includes(property.type)) {
      const options = document.createElement("input");
      options.type = "text";
      options.className = "database-property-options";
      options.value = property.options.map((option) => option.name).join(", ");
      options.placeholder = t("database.optionsPlaceholder");
      options.setAttribute("aria-label", t("database.options"));
      options.addEventListener("change", () => {
        try {
          const names = parseDatabaseOptionNames(options.value);
          const nextOptions = reconcileDatabaseOptions(database, property, names);
          options.setCustomValidity("");
          property.options = nextOptions;
          replaceEditor({ openProperties: true, focusPropertyId: property.id });
        } catch (error) {
          options.setCustomValidity(databaseOptionValidationMessage(error));
          options.reportValidity();
          // Fail closed: keep the user's raw input visible, do not mutate the
          // canonical model, and do not trigger autosave.
        }
      });
      item.append(options);
    }

    const visibility = document.createElement("label");
    visibility.className = "database-property-visibility";
    const visible = document.createElement("input");
    visible.type = "checkbox";
    visible.checked = !getDatabaseActiveView(database).hiddenPropertyIds.includes(property.id);
    visible.disabled = property.type === "title";
    visible.addEventListener("change", () => {
      const view = getDatabaseActiveView(database);
      view.hiddenPropertyIds = visible.checked
        ? view.hiddenPropertyIds.filter((id) => id !== property.id)
        : [...new Set([...view.hiddenPropertyIds, property.id])];
      replaceEditor({ openProperties: true, focusPropertyId: property.id });
    });
    visibility.append(visible, document.createTextNode(t("database.visibleInView")));
    item.append(visibility);

    const remove = makeButton("database-delete-property", "×", t("database.deleteProperty"), { propertyId: property.id });
    remove.className = "database-property-delete";
    remove.disabled = property.type === "title" || database.properties.length <= 1;
    item.append(remove);
    list.append(item);
  });

  const add = makeButton("database-add-property", `＋ ${t("database.addProperty")}`, t("database.addProperty"));
  add.className = "database-add-property";
  add.disabled = database.properties.length >= databaseLimits.properties;
  list.append(add);
  details.append(list);
  return details;
}

function validOperatorsForProperty(property) {
  if (property.type === "checkbox") return ["checked", "unchecked"];
  if (["number", "select", "date"].includes(property.type)) return ["equals", "is_empty", "is_not_empty"];
  return ["contains", "equals", "is_empty", "is_not_empty"];
}

function createFilterValueControl(property, operator) {
  if (["is_empty", "is_not_empty", "checked", "unchecked"].includes(operator)) {
    const hidden = document.createElement("input");
    hidden.type = "hidden";
    hidden.value = "";
    return hidden;
  }
  if (property.type === "select" || property.type === "multi_select") {
    return makeSelect(
      property.options.map((option) => ({ value: option.id, label: option.name })),
      property.options[0]?.id ?? "",
      "database-filter-value",
      t("database.filterValue")
    );
  }
  const input = document.createElement("input");
  input.className = "database-filter-value";
  input.type = property.type === "number" ? "number" : property.type === "date" ? "date" : "text";
  input.placeholder = t("database.filterValue");
  input.setAttribute("aria-label", t("database.filterValue"));
  return input;
}

function createViewSettings(editor, row, database, onDirty, replaceEditor) {
